def is_valid_star(grid, x, y, size):
    n = len(grid)
    m = len(grid[0])

    # Check if the central position is '*'
    if grid[x][y] != '*':
        return False

    # Check the vertical ray upwards
    for i in range(1, size + 1):
        if x - i < 0 or grid[x - i][y] == '*':
            return False

    # Check the vertical ray downwards
    for i in range(1, size + 1):
        if x + i >= n or grid[x + i][y] == '*':
            return False

    # Check the horizontal ray to the left
    for i in range(1, size + 1):
        if y - i < 0 or grid[x][y - i] == '*':
            return False

    # Check the horizontal ray to the right
    for i in range(1, size + 1):
        if y + i >= m or grid[x][y + i] == '*':
            return False

    return True

def find_stars(grid):
    n = len(grid)
    m = len(grid[0])
    stars = []

    for x in range(n):
        for y in range(m):
            if grid[x][y] == '*':
                # Try to place the largest possible star centered at (x, y)
                max_size = min(x, n - 1 - x, y, m - 1 - y)
                while max_size > 0 and is_valid_star(grid, x, y, max_size):
                    stars.append((x + 1, y + 1, max_size))
                    break
                else:
                    return -1

    return stars

