        return 0 <= x < n and 0 <= y < m

    def can_place_star(x, y, size):
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for dx, dy in directions:
            for s in range(1, size + 1):
                nx, ny = x + dx * s, y + dy * s
                if not is_valid(nx, ny) or grid[nx][ny] != '*':
                    return False
        return True

    stars = []
    visited = [[False] * m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*' and not visited[i][j]:
                size = 1
                while can_place_star(i, j, size):
                    size += 1
                size -= 1
                stars.append((i + 1, j + 1, size))
                for dx in range(-size, size + 1):
                    for dy in range(-size, size + 1):
                        if abs(dx) + abs(dy) <= size:
                            visited[i + dx][j + dy] = True

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*' and not visited[i][j]:
                return -1

    return stars

